<?php

declare(strict_types=1);

namespace PhpAiToolkit\TreeGuard\Filesystem;

/**
 * The direct, exclusion-filtered contents of one scanned directory.
 *
 * @property-read string $relativePath
 * @property-read list<string> $fileNames
 * @property-read list<string> $dirNames
 */
final class DirectoryListing
{
    /**
     * Creates one directory listing with sorted entry names.
     *
     * @param list<string> $fileNames
     * @param list<string> $dirNames
     */
    public function __construct(
        /** @readonly */
        private string $relativePath,
        /** @readonly */
        private array $fileNames,
        /** @readonly */
        private array $dirNames,
    ) {
    }

    /**
     * Provides read-only access to the immutable properties.
     *
     * @return mixed the value of the requested property
     */
    public function __get(string $name): mixed
    {
        return match ($name) {
            'relativePath' => $this->relativePath,
            'fileNames' => $this->fileNames,
            'dirNames' => $this->dirNames,
            default => null,
        };
    }
}
=== src/TreeGuard/Filesystem/DirectoryListingReader.php
<?php

declare(strict_types=1);

namespace PhpAiToolkit\TreeGuard\Filesystem;

use function is_dir;

use PhpAiToolkit\TreeGuard\TreeGuardException;

use function scandir;
use function sort;
use function sprintf;

/**
 * Reads the direct entries of one directory from the filesystem.
 */
final class DirectoryListingReader
{
    /**
     * Returns the sorted direct file and directory names of one directory.
     *
     * @return array{files: list<string>, dirs: list<string>}
     *
     * @throws TreeGuardException when the directory cannot be read
     */
    public function read(string $absolutePath): array
    {
        if (!is_dir($absolutePath)) {
            throw new TreeGuardException(sprintf('Failed to read directory: %s', $absolutePath));
        }

        $entries = @scandir($absolutePath);
        if ($entries === false) {
            throw new TreeGuardException(sprintf('Failed to read directory: %s', $absolutePath));
        }

        $files = [];
        $dirs = [];
        foreach ($entries as $entry) {
            if ($entry === '.' || $entry === '..') {
                continue;
            }
            if (is_dir($absolutePath . '/' . $entry)) {
                $dirs[] = $entry;
            } else {
                $files[] = $entry;
            }
        }

        sort($files);
        sort($dirs);

        return ['files' => $files, 'dirs' => $dirs];
    }
}
